import React from "react";

import styles from "./SegmentedControl.module.css";

export interface SegmentedControlOption {
  value: string;
  label: string;
}

export interface SegmentedControlProps {
  value: string;
  options: SegmentedControlOption[];
  onChange: (value: string) => void;
  label?: string;
  hint?: string;
  ariaLabel?: string;
  className?: string;
  compact?: boolean;
}

export function SegmentedControl({
  value,
  options,
  onChange,
  label,
  hint,
  ariaLabel,
  className = "",
  compact = false,
}: SegmentedControlProps) {
  const optionRefs = React.useRef<Map<string, HTMLButtonElement>>(new Map());

  const setOptionRef = React.useCallback((optionValue: string, node: HTMLButtonElement | null) => {
    if (node) {
      optionRefs.current.set(optionValue, node);
    } else {
      optionRefs.current.delete(optionValue);
    }
  }, []);

  const focusOption = React.useCallback((optionValue: string) => {
    optionRefs.current.get(optionValue)?.focus();
  }, []);

  const handleOptionKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>, optionValue: string) => {
      if (!options.length) {
        return;
      }

      const currentIndex = options.findIndex((option) => option.value === optionValue);
      if (currentIndex === -1) {
        return;
      }

      let nextIndex: number | null = null;

      switch (event.key) {
        case "ArrowRight":
        case "ArrowDown":
          nextIndex = (currentIndex + 1) % options.length;
          break;
        case "ArrowLeft":
        case "ArrowUp":
          nextIndex = (currentIndex - 1 + options.length) % options.length;
          break;
        case "Home":
          nextIndex = 0;
          break;
        case "End":
          nextIndex = options.length - 1;
          break;
        default:
          return;
      }

      event.preventDefault();
      const nextValue = options[nextIndex]!.value;
      onChange(nextValue);
      queueMicrotask(() => focusOption(nextValue));
    },
    [focusOption, onChange, options],
  );

  return (
    <div className={`${styles.wrapper} ${className}`.trim()}>
      {label ? <div className={styles.label}>{label}</div> : null}
      <div
        className={`${styles.track} ${compact ? styles.trackCompact : ""}`.trim()}
        role="radiogroup"
        aria-label={ariaLabel || label}
      >
        {options.map((option) => {
          const isActive = option.value === value;
          return (
            <button
              key={option.value}
              ref={(node) => setOptionRef(option.value, node)}
              type="button"
              role="radio"
              aria-checked={isActive}
              tabIndex={isActive ? 0 : -1}
              className={`${styles.option} ${isActive ? styles.optionActive : ""} ${compact ? styles.optionCompact : ""}`.trim()}
              onClick={() => onChange(option.value)}
              onKeyDown={(event) => handleOptionKeyDown(event, option.value)}
            >
              {option.label}
            </button>
          );
        })}
      </div>
      {hint ? <div className={styles.hint}>{hint}</div> : null}
    </div>
  );
}

.wrapper {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.label {
  color: var(--text-primary);
  font-size: 0.875rem;
  font-weight: 500;
}

.hint {
  color: var(--text-secondary);
  font-size: 0.75rem;
}

.track {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--border-color);
  background: color-mix(in srgb, var(--bg-secondary) 85%, transparent);
  border-radius: 999px;
}

.trackCompact {
  padding: 2px;
}

.option {
  border: none;
  background: transparent;
  color: var(--text-secondary);
  padding: 0.5rem 0.875rem;
  border-radius: 999px;
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  cursor: pointer;
  transition: color var(--transition-fast), background-color var(--transition-fast);
}

.optionCompact {
  padding: 0.35rem 0.7rem;
}

.optionActive {
  background: var(--interactive-primary-bg);
  color: var(--interactive-primary-fg);
}
